// TextBoundaryType specifies the boundary conditions determining
// a run of text as returned from #atspi_text_get_text_at_offset,
// #atspi_text_get_text_after_offset, and #atspi_text_get_text_before_offset.
//
// This enumerationis deprecated since 2.9.90 and should not be used. Use
// AtspiTextGranularity with #atspi_text_get_string_at_offset instead.
type TextBoundaryType C.gint

const (
	// TextBoundaryChar instance is bounded by this character only. Start and
	// end offsets differ by one, by definition, for this value.
	TextBoundaryChar TextBoundaryType = iota
	// TextBoundaryWordStart: boundary condition is start of a word; i.e.
	// range is from start of one word to the start of another word.
	TextBoundaryWordStart
	// TextBoundaryWordEnd: boundary condition is the end of a word; i.e.
	// range is from the end of one word to the end of another. Some locales may
	// not distinguish between words and characters or glyphs. In particular,
	// those locales which use wholly or partially ideographic character sets.
	// In these cases, characters may be returned in lieu of multi-character
	// substrings.
	TextBoundaryWordEnd
	// TextBoundarySentenceStart: boundary condition is start of a sentence,
	// as determined by the application. Some locales or character sets may
	// not include explicit sentence delimiters, so this boundary type can not
	// always be honored. Some locales will return lines of text instead of
	// grammatical sentences.
	TextBoundarySentenceStart
	// TextBoundarySentenceEnd: boundary condition is end of a sentence,
	// as determined by the application, including the sentence-delimiting
	// character, for instance '.' Some locales or character sets may not
	// include explicit sentence delimiters, so this boundary type can not
	// always be honored. Some locales will return lines of text instead of
	// grammatical sentences.
	TextBoundarySentenceEnd
	// TextBoundaryLineStart: boundary condition is the start of a line; i.e.
	// range is from start of one line to the start of another. This generally
	// means that an end-of-line character will appear at the end of the range.
	TextBoundaryLineStart
	// TextBoundaryLineEnd: boundary condition is the end of a line; i.e. range
	// is from start of one line to the start of another. This generally means
	// that an end-of-line character will be the first character of the range.
	TextBoundaryLineEnd
)

func marshalTextBoundaryType(p uintptr) (interface{}, error) {
	return TextBoundaryType(coreglib.ValueFromNative(unsafe.Pointer(p)).Enum()), nil
}

// String returns the name in string for TextBoundaryType.
func (t TextBoundaryType) String() string {
	switch t {
	case TextBoundaryChar:
		return "Char"
	case TextBoundaryWordStart:
		return "WordStart"
	case TextBoundaryWordEnd:
		return "WordEnd"
	case TextBoundarySentenceStart:
		return "SentenceStart"
	case TextBoundarySentenceEnd:
		return "SentenceEnd"
	case TextBoundaryLineStart:
		return "LineStart"
	case TextBoundaryLineEnd:
		return "LineEnd"
	default:
		return fmt.Sprintf("TextBoundaryType(%d)", t)
	}
}

// TextClipType: enumeration used by interface Text to indicate how to treat
// characters intersecting bounding boxes.
type TextClipType C.gint

const (
	// TextClipNone: no characters/glyphs are omitted.
	TextClipNone TextClipType = iota
	// TextClipMin characters/glyphs clipped by the minimum coordinate are
	// omitted.
	TextClipMin
	// TextClipMax characters/glyphs which intersect the maximum coordinate are
	// omitted.
	TextClipMax
	// TextClipBoth: only glyphs falling entirely within the region bounded by
	// min and max are retained.
	TextClipBoth
)

func marshalTextClipType(p uintptr) (interface{}, error) {
	return TextClipType(coreglib.ValueFromNative(unsafe.Pointer(p)).Enum()), nil
}

// String returns the name in string for TextClipType.
